import itertools
def squares(n, whole=False):
    pts = set(itertools.product(range(n), repeat=2)); seen = set()
    for (x, y) in pts:
        for dx in range(-n, n + 1):
            for dy in range(-n, n + 1):
                if (dx, dy) == (0, 0): continue
                q = [(x, y), (x + dx, y + dy), (x + dx - dy, y + dy + dx), (x - dy, y + dx)]
                if all(p in pts for p in q): seen.add(frozenset(q))
    if whole: seen = {q for q in seen if {min(p[0] for p in q), max(p[0] for p in q), min(p[1] for p in q), max(p[1] for p in q)} == {0, n - 1}}
    return len(seen)
result = squares(4)

